private DataTable CallResultSet(
    SIM_Class objClass,
    string scienceId,
    string courseId,
    string classId,
    byte resultSet,
    string fromDate,
    string toDate)
{
    return objClass.GetDataTable(
        SP_DATA,
        "@ScienceID", NormalizeFilter(scienceId),
        "@CourseID", NormalizeFilter(courseId),
        "@ClassID", NormalizeFilter(classId),
        "@ResultSet", resultSet,
        "@FromDate", NormalizeDate(fromDate),
        "@ToDate", NormalizeDate(toDate));
}

private DataTable CallResultSetSafe(
    SIM_Class objClass,
    string scienceId,
    string courseId,
    string classId,
    byte resultSet,
    string fromDate,
    string toDate)
{
    try
    {
        return CallResultSet(objClass, scienceId, courseId, classId, resultSet, fromDate, toDate);
    }
    catch (Exception)
    {
        return new DataTable();
    }
}

private object NormalizeDate(string value)
{
    if (String.IsNullOrEmpty(value) || value.Trim() == "")
        return DBNull.Value;

    DateTime dtResult;
    if (DateTime.TryParse(value.Trim(), out dtResult))
        return dtResult;

    return DBNull.Value;
}

